// Node.js Backend Integration with Puppeteer (document-editor)
import puppeteer from 'puppeteer';
import templatePackage from './document-editor__corporate-offer-graphic.json';

export async function generateDocumentPdf(recordData) {
  // 1. Ingest template HTML from JSON package (exact @page size 210mm x 297mm)
  let html = templatePackage.template.html;

  // 2. Replace dynamic placeholders
  Object.entries(recordData).forEach(([key, val]) => {
    const token = new RegExp(`{{\s*${key}\s*}}`, 'g');
    html = html.replace(token, String(val ?? ''));
  });

  // 3. Render 1:1 vector PDF using headless Chrome (honors @page size & Portrait/Landscape automatically)
  const browser = await puppeteer.launch({ headless: true });
  const page = await browser.newPage();
  await page.setContent(html, { waitUntil: 'networkidle0' });

  const pdfBuffer = await page.pdf({
    preferCSSPageSize: true,
    width: '210mm',
    height: '297mm',
    printBackground: true,
    margin: { top: 0, right: 0, bottom: 0, left: 0 }
  });

  await browser.close();
  return pdfBuffer;
}
